layer21_windows AS (SELECT eid,day,x,sector,region,y,budget,observations,score_20 input_score,AVG(score_20) OVER(PARTITION BY eid ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) smooth_21,LAG(score_20,1,score_20) OVER(PARTITION BY eid ORDER BY day) peer_21,MAX(score_20) OVER(PARTITION BY eid ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)-MIN(score_20) OVER(PARTITION BY eid ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) span_21 FROM layer20_score),
layer21_score AS (SELECT eid,day,x,sector,region,y,budget,observations,CAST(0.53 AS DOUBLE)*input_score+CAST(0.29 AS DOUBLE)*smooth_21+CAST(0.18 AS DOUBLE)*peer_21+CAST(0.013 AS DOUBLE)*span_21/(1+ABS(span_21))+CAST(0.009 AS DOUBLE)*(y/budget)/(1+ABS(y/budget)) score_21 FROM layer21_windows),
layer22_windows AS (SELECT eid,day,x,sector,region,y,budget,observations,score_21 input_score,AVG(score_21) OVER(PARTITION BY eid ORDER BY day ROWS BETWEEN 7 PRECEDING AND CURRENT ROW) smooth_22,LAG(score_21,1,score_21) OVER(PARTITION BY eid ORDER BY day) peer_22,MAX(score_21) OVER(PARTITION BY eid ORDER BY day ROWS BETWEEN 7 PRECEDING AND CURRENT ROW)-MIN(score_21) OVER(PARTITION BY eid ORDER BY day ROWS BETWEEN 7 PRECEDING AND CURRENT ROW) span_22 FROM layer21_score),
layer22_score AS (SELECT eid,day,x,sector,region,y,budget,observations,CAST(0.53 AS DOUBLE)*input_score+CAST(0.29 AS DOUBLE)*smooth_22+CAST(0.18 AS DOUBLE)*peer_22+CAST(0.013 AS DOUBLE)*span_22/(1+ABS(span_22))+CAST(0.009 AS DOUBLE)*(y/budget)/(1+ABS(y/budget)) score_22 FROM layer22_windows),
layer23_windows AS (SELECT eid,day,x,sector,region,y,budget,observations,score_22 input_score,AVG(score_22) OVER(PARTITION BY eid ORDER BY day ROWS BETWEEN 8 PRECEDING AND CURRENT ROW) smooth_23,LAG(score_22,1,score_22) OVER(PARTITION BY eid ORDER BY day) peer_23,MAX(score_22) OVER(PARTITION BY eid ORDER BY day ROWS BETWEEN 8 PRECEDING AND CURRENT ROW)-MIN(score_22) OVER(PARTITION BY eid ORDER BY day ROWS BETWEEN 8 PRECEDING AND CURRENT ROW) span_23 FROM layer22_score),
layer23_score AS (SELECT eid,day,x,sector,region,y,budget,observations,CAST(0.53 AS DOUBLE)*input_score+CAST(0.29 AS DOUBLE)*smooth_23+CAST(0.18 AS DOUBLE)*peer_23+CAST(0.013 AS DOUBLE)*span_23/(1+ABS(span_23))+CAST(0.009 AS DOUBLE)*(y/budget)/(1+ABS(y/budget)) score_23 FROM layer23_windows),
deep_result AS (SELECT *,AVG(score_23) OVER(PARTITION BY eid ORDER BY day ROWS BETWEEN 14 PRECEDING AND CURRENT ROW) final_mean,RANK() OVER(PARTITION BY sector,day ORDER BY ROUND(score_23,8),eid) final_rank FROM layer23_score)
SELECT eid,day,x,score_23 score,final_mean,final_rank,budget,y,observations FROM deep_result WHERE day>=30 ORDER BY eid,day;
